	if root != nil {
		q = append(q, root)
	}
	for len(q) > 0 {
		res = append(res, q[len(q)-1].Val) // 这一层最右边的节点
		next := []*TreeNode{}
		for _, node := range q {
			if node.Left != nil {
				next = append(next, node.Left)
			}
			if node.Right != nil {
				next = append(next, node.Right)
			}
		}
		q = next
	}
	return res
}

